+import { describe, expect, it } from 'vitest';
+import { cacheKey, slug } from './slug.js';
+
+describe('slug', () => {
+  it('collapses runs of non-alphanumerics', () => {
+    expect(slug('  Hello, World!  ')).toBe('hello-world');
+  });
+
+  it('builds a stable cache key from its parts', () => {
+    expect(cacheKey(['Feature Requests', 'v2'])).toBe('feature-requests/v2');
+  });
+});
